def transform(grid):
    H,W=len(grid),len(grid[0])
    border=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # frame columns: columns containing border color
    fcols=[j for j in range(W) if any(grid[i][j]==border for i in range(H))]
    frame_c1,frame_c2=min(fcols),max(fcols)
    # right shapes: connected components of nonzero in cols > frame_c2
    R=[[grid[i][j] for j in range(frame_c2+1,W)] for i in range(H)]
    seen=set(); comps=[]
    for i in range(H):
        for j in range(len(R[0])):
            if R[i][j] and (i,j) not in seen:
                col=R[i][j]; stack=[(i,j)]; seen.add((i,j)); cells=set()
                while stack:
                    r,c=stack.pop(); cells.add((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<len(R[0]) and R[nr][nc]==col and (nr,nc) not in seen:
                                seen.add((nr,nc)); stack.append((nr,nc))
                comps.append((col,bbox(cells)))
    # bands: rows between full-border rows
    fullrows=[i for i in range(H) if all(v==border for v in grid[i])]
    out=[row[:] for row in grid]
    for a,b in zip(fullrows,fullrows[1:]):
        if b-a<2: continue
        # interior zero pattern bbox
        cells={(i,j) for i in range(a+1,b) for j in range(frame_c1+1,frame_c2) if grid[i][j]==0}
        if not cells: continue
        pat=bbox(cells)
        for col,sh in comps:
            if sh==pat:
                for i in range(a+1,b):
                    for j in range(frame_c1+1,frame_c2):
                        if grid[i][j]==0: out[i][j]=col
                break
    return out

